  /* Gradient ring + outer glow — wrapper only; button colors live in Webflow.
     Ring lives on ::before and fades via opacity so it composites on the GPU
     instead of repainting a background-position animation every frame. */
  .ltf-btn-gradient-wrap {
    position: relative;
    display: inline-block;
    padding: 2px;
    border-radius: 5px;
    background: transparent;
    transition: box-shadow 0.35s ease;
  }

